import ast, re
# Extract imports from all Python files
import os
imports = set()
for root, dirs, files in os.walk('.'):
    if '.git' in root: continue
    for f in files:
        if f.endswith('.py'):
            path = os.path.join(root, f)
            try:
                with open(path) as fh:
                    tree = ast.parse(fh.read())
                for node in ast.walk(tree):
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            imports.add(alias.name.split('.')[0])
                    elif isinstance(node, ast.ImportFrom):
                        if node.module:
                            imports.add(node.module.split('.')[0])
            except: pass
# Read requirements
with open('requirements.txt') as f:
    reqs = set()
    for line in f:
        line = line.strip()
        if line and not line.startswith('#'):
            pkg = re.split(r'[>=<\[]', line)[0].strip().lower()
            reqs.add(pkg)
# Map common import names to package names
import_to_pkg = {'sklearn':'scikit-learn', 'cv2':'opencv-python', 'PIL':'pillow', 'yaml':'pyyaml', 'wandb':'wandb'}
third_party_skip = {'src', 'os', 'sys', 'json', 'math', 'random', 'collections', 'pathlib', 'itertools', 'functools', 'typing', 'copy', 'glob', 'argparse', 'time', 'datetime', 'hashlib', 'subprocess', 'shutil', 're', 'io', 'csv', 'logging', 'string', 'abc', 'contextlib', 'warnings', 'unittest', 'textwrap', 'dataclasses', 'enum', 'struct', 'concurrent', 'multiprocessing', 'threading', 'signal', 'tempfile', 'inspect', 'traceback', 'statistics', 'operator'}
missing = []
for imp in sorted(imports):
    if imp in third_party_skip: continue
    pkg = import_to_pkg.get(imp, imp).lower()
    if pkg not in reqs and imp not in reqs:
        missing.append(f'{imp} (as {pkg})')
if missing:
    print('Imports not in requirements.txt:')
    for m in missing: print(f'  - {m}')
else:
    print('All imports covered by requirements.txt')
"

